def concatHex36(n):
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

    def to_base(x, base):
        if x == 0:
            return "0"
        out = []
        while x > 0:
            x, r = divmod(x, base)
            out.append(digits[r])
        return "".join(reversed(out))

    return to_base(n * n, 16) + to_base(n * n * n, 36)
